package com.acxiom.crm.api; import com.acxiom.crm.customer.*; import com.acxiom.crm.lead.*; import com.acxiom.crm.opportunity.*; import com.acxiom.crm.followup.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportApiController {private final CustomerRepository customers;private final LeadRepository leads;private final OpportunityRepository opps;private final FollowUpRepository followups;public ReportApiController(CustomerRepository c,LeadRepository l,OpportunityRepository o,FollowUpRepository f){customers=c;leads=l;opps=o;followups=f;} @GetMapping("/summary") public Map<String,Object> summary(){var all=opps.findAll();double pipeline=all.stream().filter(o->!List.of("Won","Lost").contains(o.getStage())).mapToDouble(o->o.getAmount()==null?0:o.getAmount()).sum();double weighted=all.stream().filter(o->!List.of("Won","Lost").contains(o.getStage())).mapToDouble(Opportunity::getWeightedValue).sum();return Map.of("customers",customers.count(),"leads",leads.count(),"opportunities",opps.count(),"followups",followups.count(),"openPipeline",pipeline,"weightedPipeline",weighted,"leadsConverted",leads.findAll().stream().filter(l->"Converted".equals(l.getStatus())).count());} @GetMapping("/pipeline") public Map<String,Double> pipeline(){Map<String,Double> out=new LinkedHashMap<>();for(Opportunity o:opps.findAll())out.merge(o.getStage(),o.getAmount()==null?0:o.getAmount(),Double::sum);return out;} }
